from pathlib import Path
import json,statistics,math,hashlib
r=Path(__file__).parent
inter=json.loads((r/'interleaved.json').read_text());checks=json.loads((r/'checks.json').read_text());assert len(inter['results'])==4 and len(checks['results'])==8
rows=[]
for x in inter['results']:
 assert x['exactParity'] and not x['errors']
 row={'animals':x['animals'],'before':statistics.median(s['base'] for s in x['samples'])/40,'after':statistics.median(s['candidate'] for s in x['samples'])/40,'peerReduction':1-sum(s['candidatePeers']['used'] for s in x['samples'])/sum(s['candidatePeers']['all'] for s in x['samples'])};rows.append(row)
for x in checks['results']:assert x['exactReplay'] and not x['errors']
report={'date':'2026-10-21','summary':rows,'method':'Six interleaved sample pairs per saved scene, each40 fixed ticks from identical snapshots; median browser-thread CPU time (CDP threadTicks TaskDuration). Rendering suspended during CPU samples. Wall times retained separately. This is not an FPS measurement.','checks':checks,'interleaved':inter,'randomizedComparisons':10000,'rejectedExperiment':'Spatial grid preserved behavior but added maintenance/sorting overhead without reliable benefit; not deployed. Conservative ordered neighbor-list reuse was chosen instead.','sourceHashes':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in (r/'source/simulations').glob('*.mjs')}}
(r/'source/simulation-behavior-results.json').write_text(json.dumps(report,indent=2))
points=json.dumps(rows);last=rows[-1];change=(1-last['after']/last['before'])*100
s=Path('simulation-population-report/source/simulation-performance.html').read_text()
a=s.index('<div class="chart">');b=s.index('<details id="page-context">',a)
s=s[:a]+'''<div class="chart"></div><div class="legend"><span><i class="dot" style="background:#ae513c"></i>Before · repeated peer checks</span><span><i class="dot" style="background:#26786c"></i>After · nearby peers reused</span><span>395 → 520: switch to expanded layout</span></div>'''+f'<p class="digest"><b>1,000 animals: {last["before"]:.2f} → {last["after"]:.2f} ms CPU per tick.</b> {last["peerReduction"]*100:.0f}% fewer pen-mates passed to the final movement check. Overall CPU differences are small and mixed; no consistent speedup established.</p>'+'''<p class="sub">10,000 exact movement comparisons · four full-scene day/night checks · exact save/restore and resource-state parity</p><details><summary>Method, hidden interiors & limitations</summary><p>Each of four saved scenes runs six interleaved pairs of40 fixed ticks. The chart shows median browser-thread CPU time per tick using Chrome threadTicks timing, with rendering suspended. This isolates behavior work from frame submission and OS scheduling waits; it does not establish an FPS gain. All identities, movement decisions, needs, resources and schedules match the baseline.</p><p>Workers inside opaque buildings already use coarse offsite behavior. Hidden bodies now skip unnecessary pose interpolation. Open pens retain full movement fidelity. A spatial-grid experiment was rejected because its overhead did not show reliable benefit for these pen sizes. The deployed change reuses one conservative, ordered nearby-peer list for steering and final swept collision checks.</p><p>The520/1,000-animal expanded boards retain existing terrain/access and care/accounting limitations. Zero collisions in these short checks is not a long-run capacity guarantee. <a href="/simulation-behavior-results.json">Full measurements and checks</a> · <a href="/simulation-performance.html">Renderer FPS comparison</a></p></details>'''+s[b:]
a=s.index('<script>const points=');b=s.index('</script>',a)+9
script='''<script>const points=POINTS;function redraw(){const box=document.querySelector('.chart'),w=Math.min(960,box.clientWidth),mobile=w<600,h=mobile?310:430,L=mobile?38:60,R=w-42,T=35,B=h-65,max=Math.max(5,Math.ceil(Math.max(...points.flatMap(p=>[p.before,p.after]))/5)*5),X=n=>L+n/1000*(R-L),Y=n=>B-n/max*(B-T);let a=[];for(let y=0;y<=max;y+=max/5)a.push(`<line x1="${L}" x2="${R}" y1="${Y(y)}" y2="${Y(y)}" stroke="#ddd5c4"/><text x="${L-9}" y="${Y(y)+4}" text-anchor="end">${y.toFixed(0)}</text>`);for(const x of [0,250,500,750,1000])a.push(`<text x="${X(x)}" y="${B+24}" text-anchor="middle">${x.toLocaleString()}</text>`);a.push(`<text x="8" y="18">CPU ms / tick · lower is better</text><text x="${w/2}" y="${h-10}" text-anchor="middle">Actual animals (+11 workers)</text>`);for(const [mode,color]of [['before','#ae513c'],['after','#26786c']]){a.push(`<polyline fill="none" stroke="${color}" stroke-width="3" points="${points.map(p=>X(p.animals)+','+Y(p[mode])).join(' ')}"/>`);points.forEach((p,i)=>{a.push(`<circle cx="${X(p.animals)}" cy="${Y(p[mode])}" r="5" fill="${color}"><title>${mode}: ${p.animals} animals, ${p[mode].toFixed(2)} ms</title></circle>`);if(!mobile||i===points.length-1)a.push(`<text x="${X(p.animals)}" y="${Y(p[mode])+(mode==='after'?21:-13)}" text-anchor="middle" style="fill:${color};font-weight:700">${p[mode].toFixed(2)}</text>`);});}box.innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Simulation CPU cost before and after neighbor reuse">${a.join('')}</svg>`;box.querySelectorAll('text').forEach(t=>t.style.fontSize=mobile?'11px':'14px')}addEventListener('resize',redraw);redraw();</script>'''.replace('POINTS',points)
s=s[:a]+script+s[b:];s=s.replace('Before & after · FPS vs units','Movement CPU · before & after').replace('FPS vs units · Abbie’s World','Movement CPU · Abbie’s World').replace('pairs of40','pairs of 40').replace('The520/1,000','The 520/1,000')
(r/'source/simulation-behavior-performance.html').write_text(s)
print(rows)
